source('R/stile.R')
raw<-read.csv('dati/fossili_da_controllare.csv',sep=';',colClasses='character',na.strings=character())
converti<-function(x) suppressWarnings(as.numeric(gsub(',','.',trimws(x),fixed=TRUE)))
d<-raw;for(v in c('diametro_tot_um','diametro_int_um','diaframma_um'))d[[v]]<-converti(raw[[v]])
verifica('numero righe importate',nrow(raw)==25)
flag<-data.frame(controllo=c('ID ripetuto','D esterno NA','D esterno ≤ 0','Interno > esterno'),n=c(sum(duplicated(d$id)),sum(is.na(d$diametro_tot_um)),sum(d$diametro_tot_um<=0,na.rm=TRUE),sum(d$diametro_int_um>d$diametro_tot_um,na.rm=TRUE)))
p<-ggplot(flag,aes(reorder(controllo,n),n,fill=controllo))+geom_col(width=.6)+coord_flip()+scale_fill_manual(values=geo)+scale_y_continuous(breaks=0:4)+labs(x=NULL,y='Righe segnalate')+theme(legend.position='none')
salva('M02','F01',p,w=5.5)
d0<-leggi('campioni_modulo1.csv');d0$densita<-d0$massa_g/d0$volume_cm3
s<-aggregate(densita~stazione,d0,mean);s$n<-as.numeric(table(d0$stazione))
p<-ggplot(s,aes(stazione,n))+geom_col(fill=geo[1],width=.6)+labs(x='Stazione',y='Provini')+scale_y_continuous(breaks=0:4)
salva('M02','F02',p)
f<-leggi('fossili_simulati.csv');a<-data.frame(caso=c('Completo','Esclusi sei valori','Imputati sei valori'),n=c(160,154,160),media=c(mean(f$diametro_tot_um),mean(f$diametro_tot_um[-(1:6)]),mean(f$diametro_tot_um[-(1:6)])))
x<-f$diametro_tot_um;x[1:6]<-NA;obs<-x[!is.na(x)];imp<-x;imp[is.na(imp)]<-mean(obs)
verifica('imputazione conserva media disponibili',abs(mean(imp)-mean(obs))<1e-12)
verifica('imputazione riduce varianza secondo identita',abs(var(imp)-(length(obs)-1)/(length(imp)-1)*var(obs))<1e-12)
b<-data.frame(caso=rep(c('Disponibili','Imputati'),c(length(obs),length(imp))),valore=c(obs,imp))
p<-ggplot(b,aes(valore,colour=caso))+geom_density(linewidth=1)+scale_colour_manual(values=geo)+labs(x='Diametro (µm)',y='Densità')
salva('M02','F03',p)
L<-data.frame(id=c('p1','p2','p3'),sito=c('A','A','B'));R<-data.frame(sito=c('A','A','B'),quota=c(10,12,20));j<-merge(L,R,by='sito')
verifica('join con moltiplicita',nrow(j)==5)
b<-data.frame(tabella=factor(c('Provini','Siti','Join'),levels=c('Provini','Siti','Join')),righe=c(nrow(L),nrow(R),nrow(j)))
p<-ggplot(b,aes(tabella,righe,fill=tabella))+geom_col(width=.6)+scale_fill_manual(values=geo)+scale_y_continuous(breaks=0:5)+labs(x=NULL,y='Righe')+theme(legend.position='none')
salva('M02','F04',p)
p<-ggplot(d,aes(diametro_tot_um,diametro_int_um))+geom_abline(slope=1,intercept=0,linetype=2,colour=geo[2])+geom_point(size=3,colour=geo[1],na.rm=TRUE)+labs(x='Diametro esterno (µm)',y='Diametro interno (µm)')+coord_equal()
salva('M02','F05',p)
ff<-data.frame(esterno=f$diametro_tot_um,spessore=f$spessore_um)
p<-ggplot(ff,aes(esterno,spessore))+geom_point(size=2.4,colour=geo[1],alpha=.7)+labs(x='Diametro esterno (µm)',y='Spessore radiale (µm)')
salva('M02','F06',p)
q<-leggi('microsonda_simulata.csv');q$rapporto_massa<-q$MgO/(q$MgO+q$FeO);q$rapporto_molare<-(q$MgO/40.304)/(q$MgO/40.304+q$FeO/71.844)
verifica('rapporto molare e frazione validi',all(q$rapporto_molare>0 & q$rapporto_molare<1))
p<-ggplot(q,aes(rapporto_massa,rapporto_molare,colour=fase_generatrice))+geom_abline(slope=1,intercept=0,linetype=2)+geom_point(size=2.8)+scale_colour_manual(values=geo)+scale_x_continuous(labels=fmt)+scale_y_continuous(labels=fmt)+labs(x='MgO/(MgO + FeO)',y='Mg/(Mg + Fe) molare')
salva('M02','F07',p)
p<-ggplot(q,aes(totale_wt,fill=fase_generatrice))+geom_histogram(binwidth=.5,boundary=100,colour=paper,position='identity',alpha=.65)+scale_fill_manual(values=geo)+labs(x='Totale ossidi (% massa)',y='Analisi')
salva('M02','F08',p+theme(plot.margin=margin(9,25,7,8)))
b<-data.frame(tolleranza=seq(.5,5,.25));b$n<-sapply(b$tolleranza,function(t)sum(abs(q$totale_wt-100)<=t))
p<-ggplot(b,aes(tolleranza,n))+geom_step(colour=geo[1],linewidth=1)+geom_point(size=2,colour=geo[1])+scale_x_continuous(labels=fmt)+labs(x='Tolleranza (punti %)' ,y='Analisi mantenute')
salva('M02','F09',p)
ok<-!duplicated(d$id)&is.finite(d$diametro_tot_um)&is.finite(d$diametro_int_um)&d$diametro_tot_um>0&d$diametro_int_um>=0&d$diametro_int_um<=d$diametro_tot_um
b<-rbind(data.frame(caso='Importati',x=d$diametro_tot_um),data.frame(caso='Compatibili',x=d$diametro_tot_um[ok]))
p<-ggplot(b,aes(x,colour=caso))+stat_ecdf(linewidth=1,na.rm=TRUE)+scale_colour_manual(values=geo)+labs(x='Diametro esterno (µm)',y='Frequenza cumulata')
salva('M02','F10',p)
write.csv(flag,'verifiche/M02_segnalazioni.csv',row.names=FALSE)
